<script setup>
import { reactive, ref } from 'vue'
const props=defineProps({party:{type:Object,required:true}}); const emit=defineEmits(['created']); const loading=ref(false); const error=ref(''); const form=reactive({title:'Поставка товаров',description:'Безопасная сделка с резервированием средств',amount:'',buyer_inn:'',seller_inn:props.party.inn})
async function submit(){ loading.value=true; error.value=''; try { const {dealsApi}=await import('../services/api'); emit('created',await dealsApi.createEscrow({...form,amount:Number(form.amount)})) }catch(e){error.value=e.message}finally{loading.value=false} }
</script>
<template><section class="shell pb-20"><div class="grid gap-8 border-t border-line pt-12 lg:grid-cols-[1fr_1.1fr]"><div><p class="eyebrow">Гарант-сделка</p><h2 class="mt-3 text-3xl font-bold md:text-4xl">Деньги под защитой до исполнения условий</h2><p class="mt-5 max-w-md leading-7 text-muted">Средства покупателя резервируются на эскроу-счёте и разблокируются только после подтверждения сделки.</p></div><form class="card p-6 md:p-8" @submit.prevent="submit"><div class="grid gap-4"><input v-model="form.title" class="field" placeholder="Название сделки"><textarea v-model="form.description" class="field min-h-24 resize-y" placeholder="Описание"></textarea><div class="grid gap-4 sm:grid-cols-2"><input v-model="form.amount" class="field" type="number" min="1" placeholder="Сумма, ₽"><input v-model="form.buyer_inn" class="field" inputmode="numeric" placeholder="ИНН покупателя"></div><input v-model="form.seller_inn" class="field" inputmode="numeric" placeholder="ИНН продавца"></div><button class="action mt-5 w-full" :disabled="loading">{{loading?'Создаём эскроу...':'Заморозить средства на эскроу'}} <span class="ml-2">↗</span></button><p v-if="error" class="text-sm text-red-400">{{error}}</p></form></div></section></template>
